import React, { useState, useEffect } from 'react';
import AppRouter from "./AppRouter";
import Footer from "./components/Footer/Footer";
import Header from "./components/Header/Header";
import ScrollToTop from "./ScrollToTop";
import ModalContact from './components/ModalWindow/ModalContact';
import ModalOverlay from './components/ModalWindow/ModalOverlay';
import './App.css'; // Import App.css

function App() {
  const [showContactModal, setShowContactModal] = useState(false);
  const [isModalOpen, setIsModalOpen] = useState(false); // Состояние, указывающее, открыто ли модальное окно

  const openContactModal = () => {
    setShowContactModal(true);
    setIsModalOpen(true); // Устанавливаем флаг, когда открываем модальное окно
  };

  const closeContactModal = () => {
    setShowContactModal(false);
    setIsModalOpen(false); // Сбрасываем флаг, когда закрываем модальное окно
  };

  useEffect(() => {
    const body = document.body;
    if (isModalOpen) {
      body.style.overflow = 'hidden'; // Запрещаем прокрутку
    } else {
      body.style.overflow = 'auto'; // Разрешаем прокрутку
    }

    // Очистка при размонтировании компонента
    return () => {
      body.style.overflow = 'auto'; // Убедитесь, что прокрутка включена при размонтировании
    };
  }, [isModalOpen]);

  return (
    <div className="appContainer" style={{ filter: isModalOpen ? 'brightness(0.5)' : 'brightness(1)' }}>
      <ScrollToTop />
      <Header />
      <AppRouter />
      <Footer openContactModal={openContactModal} />

      {showContactModal && (
        <>
          <ModalOverlay onClose={closeContactModal} />
          <ModalContact onClose={closeContactModal} />
        </>
      )}
    </div>
  );
}

export default App;
